import { useEffect, useRef, useState } from 'react';
import { Scene } from './components/Scene';
import { UIOverlay } from './components/UIOverlay';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

function App() {
  const [progress, setProgress] = useState(0);
  const [mouseInfluence, setMouseInfluence] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const mouseInfluenceRef = useRef(0);

  useEffect(() => {
    // Create scroll trigger for the entire page
    const scrollTrigger = ScrollTrigger.create({
      trigger: '#scroll-container',
      start: 'top top',
      end: 'bottom bottom',
      scrub: 0.3,
      onUpdate: (self) => {
        setProgress(self.progress);
      },
    });

    // Track the current tween to kill it before creating a new one
    let currentTween: gsap.core.Tween | null = null;
    let mouseTimeout: NodeJS.Timeout | null = null;

    // Mouse movement handler for interactive effects
    const handleMouseMove = (e: MouseEvent) => {
      const x = (e.clientX / window.innerWidth - 0.5) * 2;
      const y = (e.clientY / window.innerHeight - 0.5) * 2;
      const distance = Math.sqrt(x * x + y * y);

      mouseInfluenceRef.current = distance;

      // Kill previous tween before creating new one
      if (currentTween) {
        currentTween.kill();
      }

      // Smoothly transition mouse influence
      currentTween = gsap.to({ value: distance }, {
        value: distance,
        duration: 0.5,
        ease: 'power2.out',
        onUpdate: function() {
          setMouseInfluence((this.targets()[0] as { value: number }).value);
        }
      });

      // Reset mouse influence when not moving
      if (mouseTimeout) {
        clearTimeout(mouseTimeout);
      }
      mouseTimeout = setTimeout(() => {
        if (currentTween) {
          currentTween.kill();
        }
        currentTween = gsap.to({ value: mouseInfluenceRef.current }, {
          value: 0,
          duration: 1,
          ease: 'power2.out',
          onUpdate: function() {
            setMouseInfluence((this.targets()[0] as { value: number }).value);
          }
        });
      }, 150);
    };

    window.addEventListener('mousemove', handleMouseMove);

    return () => {
      scrollTrigger.kill();
      if (currentTween) {
        currentTween.kill();
      }
      if (mouseTimeout) {
        clearTimeout(mouseTimeout);
      }
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  return (
    <div className="bg-[#0a0a0a] text-white">
      {/* 3D Scene - Fixed background */}
      <Scene progress={progress} mouseInfluence={mouseInfluence} />

      {/* UI Overlay */}
      <UIOverlay />

      {/* Scroll container - provides scroll height */}
      <div id="scroll-container" ref={containerRef} className="relative">
        {/* Hero Section */}
        <section className="h-screen flex items-center justify-center">
          <div className="sr-only">
            {/* This section is visual only - the actual content is in UIOverlay */}
            IGLOO - Digital Experience
          </div>
        </section>

        {/* Content sections for scroll */}
        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">IGLOO</h2>
            <p className="text-sm tracking-widest text-white/50">Transformation begins</p>
          </div>
        </section>

        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">DISSOLUTION</h2>
            <p className="text-sm tracking-widest text-white/50">Breaking apart into individual elements</p>
          </div>
        </section>

        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">RECONSTRUCTION</h2>
            <p className="text-sm tracking-widest text-white/50">Forming new shapes and structures</p>
          </div>
        </section>

        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">PORTAL</h2>
            <p className="text-sm tracking-widest text-white/50">Gateway to another dimension</p>
          </div>
        </section>

        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">YETI</h2>
            <p className="text-sm tracking-widest text-white/50">The guardian emerges</p>
          </div>
        </section>

        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">M</h2>
            <p className="text-sm tracking-widest text-white/50">The final form awaits</p>
          </div>
        </section>

        {/* Final section - scroll back to top hint */}
        <section className="h-screen flex items-center justify-center">
          <div className="text-center opacity-30">
            <h2 className="text-4xl font-thin tracking-widest mb-4">CYCLE</h2>
            <p className="text-sm tracking-widest text-white/50">Return to the beginning</p>
          </div>
        </section>
      </div>
    </div>
  );
}

export default App;