import { Canvas } from '@react-three/fiber';
import { Environment, Stars } from '@react-three/drei';
import { Suspense } from 'react';
import { MorphingParticles } from './MorphingParticles';
import { SnowyLandscape } from './SnowyLandscape';

interface SceneProps {
  progress: number;
  mouseInfluence: number;
}

function LoadingFallback() {
  return (
    <mesh>
      <boxGeometry args={[1, 1, 1]} />
      <meshBasicMaterial color="#c0c0c0" wireframe />
    </mesh>
  );
}

export function Scene({ progress, mouseInfluence }: SceneProps) {
  return (
    <div className="fixed inset-0 w-full h-full">
      <Canvas
        camera={{ position: [0, 0, 8], fov: 60 }}
        gl={{
          antialias: true,
          alpha: false,
          powerPreference: 'high-performance',
        }}
        dpr={[1, 2]}
      >
        <color attach="background" args={['#0a0a0a']} />

        {/* Environment lighting */}
        <ambientLight intensity={0.3} />
        <directionalLight position={[10, 10, 5]} intensity={1} color="#ffffff" />
        <directionalLight position={[-10, -10, -5]} intensity={0.5} color="#a0c0ff" />

        {/* HDR Environment for reflections */}
        <Environment preset="city" />

        {/* Starfield background */}
        <Stars
          radius={100}
          depth={50}
          count={3000}
          factor={4}
          saturation={0}
          fade
          speed={0.5}
        />

        {/* Snowy landscape background */}
        <SnowyLandscape mouseInfluence={mouseInfluence} />

        {/* Main morphing particles */}
        <Suspense fallback={<LoadingFallback />}>
          <MorphingParticles progress={progress} mouseInfluence={mouseInfluence} />
        </Suspense>
      </Canvas>
    </div>
  );
}