import { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { vertexShader, fragmentShader } from '../shaders/morphing';

interface MorphingParticlesProps {
  progress: number;
  mouseInfluence: number;
}

const PARTICLE_COUNT = 15000;

// Generate positions for different shapes
function generateIglooPositions(count: number): Float32Array {
  const positions = new Float32Array(count * 3);
  const radius = 3;
  const height = 1.5;

  for (let i = 0; i < count; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 0.5;
    const r = radius * (1 - phi / Math.PI * 0.3);

    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.cos(phi) + height;
    const z = r * Math.sin(phi) * Math.sin(theta);

    positions[i * 3] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = z;
  }
  return positions;
}

function generateShieldPositions(count: number): Float32Array {
  const positions = new Float32Array(count * 3);

  for (let i = 0; i < count; i++) {
    const theta = Math.random() * Math.PI * 2;
    const r = 2.5 * Math.sqrt(Math.random());

    const x = r * Math.cos(theta);
    const y = r * Math.sin(theta) * 1.5;
    const z = Math.random() * 0.3;

    positions[i * 3] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = z;
  }
  return positions;
}

function generateVortexPositions(count: number): Float32Array {
  const positions = new Float32Array(count * 3);

  for (let i = 0; i < count; i++) {
    const t = Math.random() * Math.PI * 6;
    const r = 0.5 + Math.random() * 2;
    const y = (Math.random() - 0.5) * 6;

    const x = r * Math.cos(t + y * 0.5);
    const z = r * Math.sin(t + y * 0.5);

    positions[i * 3] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = z;
  }
  return positions;
}

function generateYetiPositions(count: number): Float32Array {
  const positions = new Float32Array(count * 3);

  // Body (oval shape)
  const bodyCount = Math.floor(count * 0.5);
  for (let i = 0; i < bodyCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI;
    const r = 1.5 * Math.cbrt(Math.random());

    positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    positions[i * 3 + 1] = r * Math.cos(phi) * 1.2;
    positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  }

  // Head
  const headCount = Math.floor(count * 0.25);
  for (let i = bodyCount; i < bodyCount + headCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI;
    const r = 0.8 * Math.cbrt(Math.random());

    positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    positions[i * 3 + 1] = r * Math.cos(phi) + 1.8;
    positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
  }

  // Headphones
  for (let i = bodyCount + headCount; i < count; i++) {
    const side = Math.random() > 0.5 ? 1 : -1;
    const angle = Math.random() * Math.PI * 2;

    positions[i * 3] = 0.9 * side + Math.cos(angle) * 0.1;
    positions[i * 3 + 1] = 1.8 + Math.sin(angle) * 0.3;
    positions[i * 3 + 2] = Math.sin(angle) * 0.1;
  }

  return positions;
}

function generateLetterMPositions(count: number): Float32Array {
  const positions = new Float32Array(count * 3);
  const width = 3;
  const height = 4;

  for (let i = 0; i < count; i++) {
    const segment = Math.floor(Math.random() * 4);
    let x, y;

    switch (segment) {
      case 0: // Left vertical
        x = -width * 0.5;
        y = (Math.random() - 0.5) * height;
        break;
      case 1: // Left diagonal
        x = -width * 0.5 + Math.random() * width * 0.5;
        y = height * 0.5 - Math.abs(x + width * 0.5) * 0.8;
        break;
      case 2: // Right diagonal
        x = width * 0.5 - Math.random() * width * 0.5;
        y = height * 0.5 - Math.abs(x - width * 0.5) * 0.8;
        break;
      case 3: // Right vertical
        x = width * 0.5;
        y = (Math.random() - 0.5) * height;
        break;
      default:
        x = 0;
        y = 0;
    }

    positions[i * 3] = x;
    positions[i * 3 + 1] = y;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 0.3;
  }

  return positions;
}

function generateRandomPositions(count: number): Float32Array {
  const positions = new Float32Array(count * 3);

  for (let i = 0; i < count; i++) {
    positions[i * 3] = (Math.random() - 0.5) * 10;
    positions[i * 3 + 1] = (Math.random() - 0.5) * 10;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 10;
  }

  return positions;
}

export function MorphingParticles({ progress, mouseInfluence }: MorphingParticlesProps) {
  const materialRef = useRef<THREE.ShaderMaterial>(null);

  const geometry = useMemo(() => {
    const geo = new THREE.BufferGeometry();

    // Generate all position attributes for each shape
    const iglooPositions = generateIglooPositions(PARTICLE_COUNT);
    const shieldPositions = generateShieldPositions(PARTICLE_COUNT);
    const vortexPositions = generateVortexPositions(PARTICLE_COUNT);
    const yetiPositions = generateYetiPositions(PARTICLE_COUNT);
    const letterMPositions = generateLetterMPositions(PARTICLE_COUNT);
    const randomPositions = generateRandomPositions(PARTICLE_COUNT);

    // Set all attributes
    geo.setAttribute('positionIgloo', new THREE.BufferAttribute(iglooPositions, 3));
    geo.setAttribute('positionShield', new THREE.BufferAttribute(shieldPositions, 3));
    geo.setAttribute('positionVortex', new THREE.BufferAttribute(vortexPositions, 3));
    geo.setAttribute('positionYeti', new THREE.BufferAttribute(yetiPositions, 3));
    geo.setAttribute('positionLetterM', new THREE.BufferAttribute(letterMPositions, 3));
    geo.setAttribute('randomPosition', new THREE.BufferAttribute(randomPositions, 3));

    // Generate particle indices
    const indices = new Float32Array(PARTICLE_COUNT);
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      indices[i] = i;
    }
    geo.setAttribute('particleIndex', new THREE.BufferAttribute(indices, 1));

    // Set default position as igloo
    geo.setAttribute('position', new THREE.BufferAttribute(iglooPositions.slice(), 3));

    return geo;
  }, []);

  const uniforms = useMemo(
    () => ({
      uTime: { value: 0 },
      uProgress: { value: 0 },
      uMouseInfluence: { value: 0 },
      uColor1: { value: new THREE.Color('#e8e8e8') }, // Silver - Igloo
      uColor2: { value: new THREE.Color('#c0c0c0') }, // Gray - Blocks
      uColor3: { value: new THREE.Color('#a0d8ef') }, // Light blue - Shield
      uColor4: { value: new THREE.Color('#ffffff') }, // White - Vortex
    }),
    []
  );

  // Update uniforms
  useFrame((state) => {
    if (materialRef.current) {
      materialRef.current.uniforms.uTime.value = state.clock.elapsedTime;
      materialRef.current.uniforms.uProgress.value = progress;
      materialRef.current.uniforms.uMouseInfluence.value = mouseInfluence;
    }
  });

  return (
    <points geometry={geometry}>
      <shaderMaterial
        ref={materialRef}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        uniforms={uniforms}
        transparent
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}