import { useState, useEffect } from 'react';

export function UIOverlay() {
  const [scrolled, setScrolled] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const scrollHeight = document.documentElement.scrollHeight - window.innerHeight;
      const scrollTop = window.scrollY;
      setScrolled(scrollTop / scrollHeight);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = ['Work', 'About', 'Contact'];
  const stages = ['Igloo', 'Blocks', 'Shield', 'Vortex', 'Yeti', 'M'];

  const getCurrentStage = () => {
    const index = Math.floor(scrolled * 6);
    return stages[Math.min(index, stages.length - 1)];
  };

  return (
    <div className="fixed inset-0 pointer-events-none z-10">
      {/* Logo */}
      <div className="absolute top-6 left-8">
        <h1 className="text-3xl font-light tracking-[0.3em] text-white/90 font-mono">
          IGLOO
        </h1>
      </div>

      {/* Navigation */}
      <nav className="absolute top-6 right-8">
        <ul className="flex gap-8">
          {navItems.map((item) => (
            <li key={item}>
              <button
                className="text-sm tracking-widest text-white/70 hover:text-white transition-colors uppercase font-light"
                style={{ fontFamily: 'monospace' }}
              >
                {item}
              </button>
            </li>
          ))}
        </ul>
      </nav>

      {/* Progress indicator */}
      <div className="absolute left-8 top-1/2 -translate-y-1/2">
        <div className="h-32 w-px bg-white/20">
          <div
            className="w-full bg-white/80 transition-all duration-300"
            style={{ height: `${scrolled * 100}%` }}
          />
        </div>
        <div className="mt-4 text-xs text-white/50 font-mono tracking-wider">
          {Math.round(scrolled * 100)}%
        </div>
      </div>

      {/* Stage indicator */}
      <div className="absolute right-8 top-1/2 -translate-y-1/2">
        <div className="text-right">
          <div className="text-xs text-white/40 font-mono tracking-widest mb-1">
            CURRENT FORM
          </div>
          <div className="text-lg text-white/80 font-light tracking-widest">
            {getCurrentStage()}
          </div>
        </div>
      </div>

      {/* Scroll indicator at bottom */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2">
        <div className="text-center">
          <div className="text-xs text-white/40 font-mono tracking-widest mb-2">
            SCROLL TO EXPLORE
          </div>
          <div className="w-6 h-10 border border-white/30 rounded-full mx-auto flex justify-center pt-2">
            <div className="w-1 h-2 bg-white/50 rounded-full animate-bounce" />
          </div>
        </div>
      </div>

      {/* Title at hero section */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-center pointer-events-auto">
        <div className="opacity-0 animate-[fadeIn_2s_ease-out_0.5s_forwards]">
          <h2 className="text-6xl md:text-8xl font-thin tracking-[0.2em] text-white/90 mb-4">
            IGLOO
          </h2>
          <p className="text-sm tracking-[0.5em] text-white/50 font-light">
            DIGITAL EXPERIENCE
          </p>
        </div>
      </div>
    </div>
  );
}