export const vertexShader = `
  uniform float uTime;
  uniform float uProgress;
  uniform float uMouseInfluence;

  attribute vec3 positionIgloo;
  attribute vec3 positionShield;
  attribute vec3 positionVortex;
  attribute vec3 positionYeti;
  attribute vec3 positionLetterM;

  attribute vec3 randomPosition;

  attribute float particleIndex;

  varying vec3 vNormal;
  varying vec3 vPosition;
  varying float vProgress;
  varying vec2 vUv;
  varying float vDepth;

  // Easing function
  float easeInOutCubic(float t) {
    return t < 0.5 ? 4.0 * t * t * t : 1.0 - pow(-2.0 * t + 2.0, 3.0) / 2.0;
  }

  // Smooth transition between two positions
  vec3 morphPosition(vec3 from, vec3 to, float t) {
    float eased = easeInOutCubic(t);
    return mix(from, to, eased);
  }

  // Get position based on current progress (stage of transformation)
  vec3 getTargetPosition(float prog) {
    vec3 pos = positionIgloo;

    // Stage 0-15%: Igloo to floating blocks
    if (prog < 0.15) {
      float t = prog / 0.15;
      pos = morphPosition(positionIgloo, randomPosition, t);
    }
    // Stage 15-30%: Blocks to Shield
    else if (prog < 0.30) {
      float t = (prog - 0.15) / 0.15;
      pos = morphPosition(randomPosition, positionShield, t);
    }
    // Stage 30-45%: Shield to Vortex
    else if (prog < 0.45) {
      float t = (prog - 0.30) / 0.15;
      pos = morphPosition(positionShield, positionVortex, t);
    }
    // Stage 45-60%: Vortex to Yeti
    else if (prog < 0.60) {
      float t = (prog - 0.45) / 0.15;
      pos = morphPosition(positionVortex, positionYeti, t);
    }
    // Stage 60-75%: Yeti to Letter M
    else if (prog < 0.75) {
      float t = (prog - 0.60) / 0.15;
      pos = morphPosition(positionYeti, positionLetterM, t);
    }
    // Stage 75-100%: Letter M back to Igloo (cycle)
    else {
      float t = (prog - 0.75) / 0.25;
      pos = morphPosition(positionLetterM, positionIgloo, t);
    }

    return pos;
  }

  void main() {
    vUv = uv;
    vProgress = uProgress;

    // Get the target position based on scroll progress
    vec3 targetPos = getTargetPosition(uProgress);

    // Add some floating animation
    float floatOffset = sin(uTime * 0.5 + particleIndex * 0.1) * 0.1;
    targetPos.y += floatOffset;

    // Add mouse influence (subtle)
    vec3 mouseEffect = vec3(
      sin(uTime * 0.3 + position.y) * uMouseInfluence * 0.5,
      cos(uTime * 0.4 + position.x) * uMouseInfluence * 0.5,
      sin(uTime * 0.2 + position.z) * uMouseInfluence * 0.3
    );
    targetPos += mouseEffect;

    // Calculate normal for lighting
    vNormal = normalize(normalMatrix * normal);
    vPosition = targetPos;

    // Depth for fragment shader effects
    vDepth = length(targetPos);

    vec4 mvPosition = modelViewMatrix * vec4(targetPos, 1.0);
    gl_Position = projectionMatrix * mvPosition;

    // Size variation based on progress
    float baseSize = 3.0;
    float sizeMultiplier = 1.0 + sin(uProgress * 6.28) * 0.3;
    gl_PointSize = baseSize * sizeMultiplier * (300.0 / -mvPosition.z);
  }
`;

export const fragmentShader = `
  uniform float uTime;
  uniform float uProgress;
  uniform vec3 uColor1;
  uniform vec3 uColor2;
  uniform vec3 uColor3;
  uniform vec3 uColor4;

  varying vec3 vNormal;
  varying vec3 vPosition;
  varying float vProgress;
  varying vec2 vUv;
  varying float vDepth;

  // Simplex noise function for texture
  vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
  vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
  vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
  vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

  float snoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);

    vec3 i  = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);

    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);

    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;

    i = mod289(i);
    vec4 p = permute(permute(permute(
              i.z + vec4(0.0, i1.z, i2.z, 1.0))
            + i.y + vec4(0.0, i1.y, i2.y, 1.0))
            + i.x + vec4(0.0, i1.x, i2.x, 1.0));

    float n_ = 0.142857142857;
    vec3 ns = n_ * D.wyz - D.xzx;

    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);

    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);

    vec4 x = x_ *ns.x + ns.yyyy;
    vec4 y = y_ *ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);

    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);

    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));

    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;

    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);

    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
    p0 *= norm.x;
    p1 *= norm.y;
    p2 *= norm.z;
    p3 *= norm.w;

    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
  }

  void main() {
    // Create metallic/shiny look based on normal
    vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
    float diffuse = max(dot(vNormal, lightDir), 0.0);

    // Specular highlight for metallic effect
    vec3 viewDir = normalize(cameraPosition - vPosition);
    vec3 reflectDir = reflect(-lightDir, vNormal);
    float specular = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

    // Fresnel effect for edge glow
    float fresnel = pow(1.0 - max(dot(viewDir, vNormal), 0.0), 3.0);

    // Color gradient based on progress
    vec3 baseColor;
    if (vProgress < 0.25) {
      baseColor = mix(uColor1, uColor2, vProgress * 4.0);
    } else if (vProgress < 0.5) {
      baseColor = mix(uColor2, uColor3, (vProgress - 0.25) * 4.0);
    } else if (vProgress < 0.75) {
      baseColor = mix(uColor3, uColor4, (vProgress - 0.5) * 4.0);
    } else {
      baseColor = mix(uColor4, uColor1, (vProgress - 0.75) * 4.0);
    }

    // Add noise texture
    float noise = snoise(vPosition * 2.0 + uTime * 0.1) * 0.1 + 0.9;

    // Combine all lighting
    vec3 finalColor = baseColor * (diffuse * 0.6 + 0.4);
    finalColor += vec3(1.0) * specular * 0.8;
    finalColor += baseColor * fresnel * 0.5;
    finalColor *= noise;

    // Add subtle glow based on progress (transformation flash)
    float glowPulse = sin(uProgress * 6.28) * 0.5 + 0.5;
    finalColor += baseColor * glowPulse * 0.2;

    gl_FragColor = vec4(finalColor, 1.0);
  }
`;