import { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

interface SnowyLandscapeProps {
  mouseInfluence: number;
}

export function SnowyLandscape({ mouseInfluence }: SnowyLandscapeProps) {
  const meshRef = useRef<THREE.Mesh>(null);

  // Use the mouseInfluence prop directly instead of unused ref
  const mouseRef = useRef({ x: mouseInfluence, y: mouseInfluence });

  // Create terrain geometry with noise
  const geometry = useMemo(() => {
    const geo = new THREE.PlaneGeometry(50, 50, 128, 128);
    const positions = geo.attributes.position.array as Float32Array;

    // Generate hills using sine waves
    for (let i = 0; i < positions.length; i += 3) {
      const x = positions[i];
      const z = positions[i + 1];

      // Multiple frequency noise for natural terrain
      const height =
        Math.sin(x * 0.3) * Math.cos(z * 0.3) * 1.5 +
        Math.sin(x * 0.7 + 1) * Math.cos(z * 0.5) * 0.8 +
        Math.sin(x * 1.5 + 2) * Math.cos(z * 1.2) * 0.3;

      positions[i + 2] = height;
    }

    geo.computeVertexNormals();
    return geo;
  }, []);

  // Update terrain animation
  useFrame((state) => {
    if (meshRef.current) {
      // Gentle rotation
      meshRef.current.rotation.z = Math.sin(state.clock.elapsedTime * 0.05) * 0.02;

      // Mouse influence - subtle tilt
      const targetRotationX = mouseRef.current.y * 0.1;
      const targetRotationY = mouseRef.current.x * 0.1;

      meshRef.current.rotation.x = THREE.MathUtils.lerp(
        meshRef.current.rotation.x,
        targetRotationX,
        0.05
      );
      meshRef.current.rotation.y = THREE.MathUtils.lerp(
        meshRef.current.rotation.y,
        targetRotationY,
        0.05
      );
    }
  });

  return (
    <group position={[0, -4, -10]}>
      {/* Main terrain */}
      <mesh
        ref={meshRef}
        geometry={geometry}
        rotation={[-Math.PI / 2, 0, 0]}
      >
        <meshStandardMaterial
          color="#e8e8e8"
          roughness={0.9}
          metalness={0.1}
          wireframe={false}
        />
      </mesh>

      {/* Ground plane for extra depth */}
      <mesh position={[0, -0.5, -5]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[100, 100]} />
        <meshStandardMaterial
          color="#1a1a1a"
          roughness={1}
          metalness={0}
        />
      </mesh>

      {/* Fog particles (distant mountains) */}
      {[...Array(5)].map((_, i) => (
        <mesh
          key={i}
          position={[
            (i - 2) * 8,
            0,
            -15 - Math.random() * 10,
          ]}
        >
          <sphereGeometry args={[3 + Math.random() * 2, 16, 16]} />
          <meshStandardMaterial
            color="#d0d0d0"
            transparent
            opacity={0.3}
            roughness={1}
          />
        </mesh>
      ))}
    </group>
  );
}